sp_widget.client_script:
api.controller = function($scope, $sce) {

    var c = this;

    c.messages = [];
    c.currentInput = '';
    c.isLoading = false;

    c.sendMessage = function() {

        var question = (c.currentInput || '').trim();

        if (!question || c.isLoading) {
            return;
        }

        c.isLoading = true;
        c.currentInput = '';

        c.messages.push({
            question: question,
            answer: null,
            answerHtml: null
        });

        var historyForServer = [];
        for (var i = 0; i < c.messages.length - 1; i++) {
            historyForServer.push({
                question: c.messages[i].question,
                answer: c.messages[i].answer
            });
        }

        c.server.get({
            action: 'sendMessage',
            question: question,
            conversationHistory: historyForServer
        }).then(function(response) {

            var lastMsg = c.messages[c.messages.length - 1];
            var rawAnswer = response.data.answer || response.data.error || "Something went wrong. Please try again.";

            lastMsg.answer = rawAnswer;
            lastMsg.answerHtml = $sce.trustAsHtml(c.formatResponse(rawAnswer));
            c.isLoading = false;

            setTimeout(function() {
                var container = document.querySelector('.incentiq-messages');
                if (container) {
                    container.scrollTop = container.scrollHeight;
                }
            }, 50);

        }, function() {

            var lastMsg = c.messages[c.messages.length - 1];
            lastMsg.answer = "Something went wrong. Please try again.";
            lastMsg.answerHtml = $sce.trustAsHtml("Something went wrong. Please try again.");
            c.isLoading = false;
        });
    };

    c.formatResponse = function(text) {

        if (!text) {
            return text;
        }

        text = text
            .replace(/\*\*(.*?)\*\*/g, '$1')
            .replace(/^#+\s*/gm, '')
            .replace(/\*(.*?)\*/g, '$1');

        var knownHeaders = ["Summary", "Key Details", "Data Available", "Suggested Follow-up Questions"];
        var lines = text.split('\n');
        var html = '';
        var inList = false;

        for (var i = 0; i < lines.length; i++) {

            var line = lines[i].trim();

            if (!line) {
                continue;
            }

            var isHeader = false;
            for (var h = 0; h < knownHeaders.length; h++) {
                if (line === knownHeaders[h]) {
                    isHeader = true;
                    break;
                }
            }

            var bulletContent = null;
            if (line.indexOf('- ') === 0) {
                bulletContent = line.substring(2);
            } else if (line.indexOf('\u2022 ') === 0) {
                bulletContent = line.substring(2);
            }

            var isTotalLine = bulletContent !== null && /total/i.test(bulletContent);

            if (isHeader) {
                if (inList) {
                    html += '</ul>';
                    inList = false;
                }
                html += '<div class="incentiq-section-header">' + line + '</div>';

            } else if (isTotalLine) {
                if (inList) {
                    html += '</ul>';
                    inList = false;
                }
                html += '<div class="incentiq-total-line">' + bulletContent + '</div>';

            } else if (bulletContent !== null) {
                if (!inList) {
                    html += '<ul class="incentiq-section-list">';
                    inList = true;
                }
                html += '<li>' + bulletContent + '</li>';

            } else {
                if (inList) {
                    html += '</ul>';
                    inList = false;
                }
                html += '<div class="incentiq-section-text">' + line + '</div>';
            }
        }

        if (inList) {
            html += '</ul>';
        }

        return html;
    };
};

sp_widget.css:
.incentiq-page { --ink: #10182B; --slate: #5B6472; --bg: #F4F5F7; --surface: #FFFFFF; --border: #E3E6EB; --accent: #146356; --accent-dark: #0F4F45; --accent-soft: #EAF3F0; --accent-mid: #BFE0D6; display: flex; gap: 16px; height: 85vh; max-height: 800px; width: 100%; padding: 24px; box-sizing: border-box; background: var(--bg); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
* { box-sizing: border-box; }
.incentiq-side { width: 250px; border: 1px solid var(--border); border-radius: 16px; padding: 22px 18px; background: rgba(255, 255, 255, 0.85); backdrop-filter: blur(6px); overflow-y: auto; box-shadow: 0 1px 3px rgba(16, 24, 43, 0.05); }
.incentiq-label { display: flex; align-items: center; font-size: 11px; color: var(--slate); font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em; margin: 0 0 12px 0; }
.incentiq-label-tab { width: 4px; height: 12px; border-radius: 2px; background: var(--accent); margin-right: 8px; flex-shrink: 0; }
.incentiq-list { list-style: none; padding: 0; margin: 0 0 24px 0; }
.incentiq-list li { display: flex; align-items: center; gap: 10px; padding: 9px 10px; font-size: 13.5px; font-weight: 500; color: var(--ink); border-radius: 10px; margin-bottom: 2px; cursor: pointer; transition: background 0.18s ease, transform 0.15s ease, color 0.18s ease; }
.incentiq-list li:hover { background: var(--accent-soft); color: var(--accent-dark); transform: translateX(2px); }
.incentiq-icon { display: flex; align-items: center; justify-content: center; width: 18px; height: 18px; color: var(--slate); flex-shrink: 0; transition: color 0.18s ease; }
.incentiq-icon svg { width: 100%; height: 100%; }
.incentiq-list li:hover .incentiq-icon { color: var(--accent); }
.incentiq-opps-card { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px 14px; border-radius: 14px; border: 1px dashed var(--border); background: var(--bg); text-align: center; }
.incentiq-opps-icon { width: 20px; height: 20px; color: var(--accent); opacity: 0.6; }
.incentiq-opps-icon svg { width: 100%; height: 100%; }
.incentiq-opps-count { font-size: 22px; font-weight: 700; color: var(--accent); line-height: 1; }
.incentiq-opps-text { font-size: 12.5px; color: #8A909A; font-weight: 500; }
.incentiq-main { flex: 1; display: flex; flex-direction: column; border: 1px solid var(--border); border-radius: 16px; padding: 0; background: var(--surface); min-height: 0; box-shadow: 0 1px 3px rgba(16, 24, 43, 0.05); overflow: hidden; }
.incentiq-title { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 16px 28px; border-bottom: 1px solid var(--border); background: linear-gradient(180deg, #FCFDFD 0%, #FFFFFF 100%); position: relative; flex-shrink: 0; }
.incentiq-title-left { position: relative; z-index: 2; }
.incentiq-title-text { display: block; font-weight: 700; font-size: 18px; color: var(--ink); letter-spacing: -0.01em; }
.incentiq-title-sub { display: block; font-size: 12px; color: var(--slate); margin-top: 4px; max-width: 320px; }
.incentiq-hero-art { position: relative; width: 180px; height: 64px; flex-shrink: 0; border-radius: 12px; background: linear-gradient(135deg, var(--accent-soft) 0%, #F5FAF8 60%, #FFFFFF 100%); overflow: hidden; display: none; }
@media (min-width: 900px) { .incentiq-hero-art { display: block; } }
.incentiq-hero-dot { position: absolute; border-radius: 50%; background: var(--accent-mid); opacity: 0.5; }
.incentiq-hero-dot-1 { width: 8px; height: 8px; top: 8px; left: 16px; }
.incentiq-hero-dot-2 { width: 5px; height: 5px; top: 22px; left: 46px; }
.incentiq-hero-dot-3 { width: 11px; height: 11px; bottom: 8px; left: 10px; opacity: 0.35; }
.incentiq-hero-bars { position: absolute; right: 36px; bottom: 8px; display: flex; align-items: flex-end; gap: 4px; height: 40px; }
.incentiq-bar { width: 6px; height: var(--h); border-radius: 3px 3px 0 0; background: linear-gradient(180deg, var(--accent) 0%, var(--accent-dark) 100%); opacity: 0.9; }
.incentiq-hero-coin { position: absolute; right: 4px; bottom: 6px; width: 26px; height: 26px; border-radius: 50%; background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%); color: #ffffff; font-weight: 700; font-size: 12px; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 10px rgba(20, 99, 86, 0.3); }
.incentiq-messages { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; min-height: 0; padding: 24px 28px; }
.incentiq-empty { margin: auto; text-align: center; max-width: 560px; }
.incentiq-empty-icon { width: 56px; height: 56px; margin: 0 auto 18px auto; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #ffffff 0%, var(--accent-soft) 55%, var(--accent-mid) 100%); display: flex; align-items: center; justify-content: center; color: var(--accent); box-shadow: 0 6px 16px rgba(20, 99, 86, 0.14); }
.incentiq-empty-icon svg { width: 24px; height: 24px; }
.incentiq-empty-title { font-size: 18px; font-weight: 700; color: var(--ink); margin: 0 0 10px 0; line-height: 1.35; }
.incentiq-empty-brand { color: var(--accent); }
.incentiq-empty-sub { font-size: 13.5px; color: var(--slate); line-height: 1.65; margin: 0 0 26px 0; }
.incentiq-quick-actions { display: flex; flex-wrap: nowrap; gap: 10px; justify-content: center; }
.incentiq-quick-card { display: flex; align-items: center; gap: 8px; padding: 11px 13px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); font-size: 12.5px; font-weight: 500; color: var(--ink); cursor: pointer; text-align: left; flex: 1 1 0; min-width: 0; font-family: inherit; transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease; }
.incentiq-quick-card:hover { transform: translateY(-3px); box-shadow: 0 10px 22px rgba(16, 24, 43, 0.09); border-color: var(--accent-mid); }
.incentiq-quick-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.incentiq-quick-icon { width: 26px; height: 26px; flex-shrink: 0; border-radius: 8px; background: var(--accent-soft); color: var(--accent); display: flex; align-items: center; justify-content: center; }
.incentiq-quick-icon svg { width: 15px; height: 15px; }
.incentiq-turn { display: flex; flex-direction: column; gap: 8px; }
.incentiq-bubble { border-radius: 14px; font-size: 14px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; line-height: 1.65; }
.incentiq-bubble-user { align-self: flex-end; background: var(--accent-soft); color: var(--accent-dark); padding: 9px 14px; max-width: 62%; width: fit-content; white-space: pre-wrap; font-weight: 500; border: 1px solid var(--accent-mid); }
.incentiq-bubble-answer { align-self: flex-start; background: var(--surface); color: var(--ink); padding: 16px 20px; max-width: 80%; white-space: normal; border: 1px solid var(--border); box-shadow: 0 2px 10px rgba(16, 24, 43, 0.05); }
.incentiq-thinking { align-self: flex-start; display: flex; gap: 6px; padding: 16px 20px; background: var(--surface); border: 1px solid var(--border); border-radius: 14px; box-shadow: 0 2px 10px rgba(16, 24, 43, 0.05); }
.incentiq-shimmer-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); animation: incentiq-shimmer 1.3s infinite ease-in-out; }
.incentiq-shimmer-dot:nth-child(2) { animation-delay: 0.16s; }
.incentiq-shimmer-dot:nth-child(3) { animation-delay: 0.32s; }
@keyframes incentiq-shimmer { 0%, 80%, 100% { opacity: 0.25; transform: scale(0.75); } 40% { opacity: 1; transform: scale(1.05); } }
@media (prefers-reduced-motion: reduce) { .incentiq-shimmer-dot { animation: none; opacity: 0.6; } }
.incentiq-section-header { font-weight: 700; font-size: 12.5px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--accent); margin-top: 14px; margin-bottom: 7px; padding-bottom: 5px; border-bottom: 1px solid var(--accent-soft); }
.incentiq-section-header:first-child { margin-top: 0; }
.incentiq-section-text { margin-bottom: 7px; line-height: 1.65; }
.incentiq-section-list { margin: 0 0 7px 0; padding-left: 19px; }
.incentiq-section-list li { margin-bottom: 5px; line-height: 1.6; }
.incentiq-total-line { font-family: ui-monospace, "SF Mono", "Cascadia Code", Consolas, monospace; font-weight: 600; font-size: 13.5px; color: var(--ink); background: var(--accent-soft); display: inline-block; padding: 7px 13px; border-radius: 8px; margin-top: 9px; }
.incentiq-inputrow { display: flex; gap: 12px; padding: 18px 28px; border-top: 1px solid var(--border); background: rgba(255, 255, 255, 0.9); backdrop-filter: blur(4px); flex-shrink: 0; }
.incentiq-textbox { flex: 1; padding: 13px 18px; border: 1px solid var(--border); border-radius: 999px; font-size: 14px; color: var(--ink); background: var(--bg); transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease; }
.incentiq-textbox::placeholder { color: #9AA1AC; }
.incentiq-textbox:focus { outline: none; border-color: var(--accent); background: var(--surface); box-shadow: 0 0 0 4px var(--accent-soft); }
.incentiq-sendbtn { display: flex; align-items: center; gap: 8px; padding: 12px 24px; border: none; border-radius: 999px; background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%); color: #ffffff; font-weight: 600; font-size: 13.5px; cursor: pointer; transition: transform 0.15s ease, box-shadow 0.15s ease; box-shadow: 0 4px 12px rgba(20, 99, 86, 0.25); }
.incentiq-sendbtn:hover:not(:disabled) { transform: translateY(-1px); box-shadow: 0 6px 16px rgba(20, 99, 86, 0.32); }
.incentiq-sendbtn:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.incentiq-sendbtn:disabled { background: #C7CCD3; box-shadow: none; cursor: not-allowed; }
.incentiq-send-icon { width: 15px; height: 15px; }
@media (max-width: 900px) { .incentiq-page { flex-direction: column; height: auto; max-height: none; } .incentiq-side { width: 100%; } }
@media (max-width: 560px) { .incentiq-quick-card { max-width: 100%; width: 100%; flex: 1 1 100%; } .incentiq-title { flex-direction: column; } }

.incentiq-provider-badge {
  display: inline-block;
  margin-top: 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  padding: 3px 9px;
  border-radius: 999px;
}

sp_widget.script:
(function() {

    data.opportunityCount = 0;

    try {
        var oppService = new x_ctans_incentnow.IncentIQOpportunityService();
        var oppResult = oppService.getOpportunities();
        data.opportunityCount = oppResult.opportunityCount || 0;
    } catch (ex) {
        gs.error("Widget :: Failed to load opportunity count: " + ex.message);
    }

    // Badge reflects the real active provider (ServiceNow / OpenAI / Claude)
    try {
        var providerAdmin = new x_ctans_incentnow.IncentIQProviderAdmin();
        var active = providerAdmin.getActiveProvider();
        data.currentAiProviderLabel = (active && active.label) ? active.label : 'ServiceNow LLM (Now LLM)';
    } catch (ex) {
        gs.error("Widget :: Failed to resolve active provider: " + ex.message);
        data.currentAiProviderLabel = 'ServiceNow LLM (Now LLM)';
    }

    if (input && input.action === 'sendMessage') {
        try {
            var orchestrator = new x_ctans_incentnow.IncentIQChatOrchestrator();
            var result = orchestrator.sendMessage(input.question, input.conversationHistory);

            if (result.success) {
                data.answer = result.message;
            } else {
                data.error = result.message;
            }
        } catch (ex) {
            gs.error("Widget :: sendMessage handling failed: " + ex.message);
            data.error = "Something went wrong while processing your question. Please try again.";
        }
    }

})();
